"""Build release guides. Requires reportlab; no scientific annotations are created."""
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
ROOT = Path(__file__).resolve().parents[1]
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='Text',fontName='Helvetica',fontSize=10.5,leading=15,spaceAfter=8))
styles.add(ParagraphStyle(name='SmallText',fontName='Helvetica',fontSize=9,leading=13,spaceAfter=7))
styles.add(ParagraphStyle(name='CompactText',fontName='Helvetica',fontSize=10,leading=13.5,spaceAfter=6))
styles['Title'].fontName='Helvetica-Bold';styles['Title'].fontSize=19;styles['Title'].leading=24
styles['Heading2'].fontName='Helvetica-Bold';styles['Heading2'].fontSize=13;styles['Heading2'].leading=18
styles['Heading2'].keepWithNext=True
styles.add(ParagraphStyle(name='CompactHeading',fontName='Helvetica-Bold',fontSize=12,leading=16,spaceBefore=7,spaceAfter=4,keepWithNext=True))

def footer(c, doc):
    c.saveState();c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#52616B'))
    c.drawString(20*mm,14*mm,'AmbiTab-Sports | Anonymous review artifact | Release 2026-10-03')
    c.drawRightString(190*mm,14*mm,str(doc.page));c.restoreState()

def pdf(rel, title, sections, body_style='Text'):
    p=ROOT/rel;p.parent.mkdir(parents=True,exist_ok=True)
    story=[Paragraph(title,styles['Title']),Spacer(1,6*mm)]
    for heading, paragraphs in sections:
        heading_style = 'CompactHeading' if body_style == 'CompactText' else 'Heading2'
        story.append(Paragraph(heading,styles[heading_style]))
        for text in paragraphs:story.append(Paragraph(text,styles[body_style]))
    doc=SimpleDocTemplate(str(p),pagesize=(210*mm,297*mm),rightMargin=20*mm,leftMargin=20*mm,
        topMargin=18*mm,bottomMargin=23*mm,title=title,author='Anonymous',creator='AmbiTab-Sports release tools')
    doc.build(story,onFirstPage=footer,onLaterPages=footer)

pdf('docs/AmbiTab-Sports_Benchmark_Description.pdf','AmbiTab-Sports: benchmark description',[
('Scope and coverage',['The release contains 360 constructed sports-data queries across club football, international football, Olympics, basketball, tennis, and Formula 1. Each domain contains 20 queries in each of three interaction tracks. Models receive no source tables. The experiments concern responses before evidence retrieval and action selection; they do not test grounded table reasoning.']),
('Tracks',['Unambiguous (U): a sufficiently specified factual request; the expected action is ANSWER. Cooperative ambiguous (C): a defensible conventional interpretation can support a useful response if disclosed; the expected action is INTERPRET. Uncooperative (X): essential missing information makes committing to a frame arbitrary; the expected action is CLARIFY. These are intended benchmark labels, not a judgment about user willingness to cooperate.']),
('Files and historical partitions',['The canonical benchmark CSV has 360 unique query IDs and 63 columns. It includes supplied construction A/B fields, final labels, acceptable interpretations, execution references, and source status. Historical train/dev/test sizes are 252/54/54; all items are used in the revised zero-shot evaluation.']),
('Provenance and factual verification',['The final construction workbook is a release view exported from the canonical CSV. The separately retained historical master is an unfinished starter, with 497 open disputes. No historical adjudicator rationales have been fabricated. Source-status claims originally supplied with the benchmark are retained as supplied_verification_status; current verification_status does not present them as independent factual checks. Six items are flagged for source review.']),
('Scientific limits',['Queries were constructed to instantiate a taxonomy; the release is not a naturally sampled user-log dataset. Independent human validation of supplied response ratings is unverified. Familiar sports facts may occur in model training data; contamination is not measured. Source verification, construction chronology, model revision SHAs, and an exact historical runtime are incomplete.'])])

pdf('docs/Annotation_Guidelines.pdf','Construction annotation guide',[
('Status of this guide',['This release guide documents the intended label schema. It does not reconstruct every historical annotation decision or establish annotator independence. The original query-annotation guide is retained under docs/archive.']),
('Track assignment',['Assign U when the entity, competition/time frame, and requested statistic are sufficiently specified to determine a target. Assign C when a conventional frame can resolve ambiguity and should be disclosed. Assign X when essential omissions lead to materially different answers and a defensible default is unavailable. Record uncertainty rather than forcing agreement from the authored draft label.']),
('Specification fields',['Record entity, temporal, domain, intent, and methodology specification separately. The primary ambiguity source identifies the main omission; fine-grained labels need not agree simply because the track agrees. Use the supplied schema and codebook values, preserving the distinction between specified, underspecified, ambiguous, and conventional-assumption labels where present.']),
('Clarification and interpretation',['Record preferred action and clarification requirement. A useful clarification question targets the missing entity, time window, competition, or statistic. Cooperative interpretation examples are possible frames rather than a unique factual gold. Disclose alternatives and the criteria used to decide whether a default is defensible.']),
('Data privilege',['Structural, value, and container references are screened to avoid requiring the user to know internal representation identifiers. This is a design choice. No with-filter/without-filter experiment is included, so improved realism or performance is not an empirical finding.']),
('Disagreements and release records',['Keep A and B source values. Final labels in this release are the supplied final decisions; the export is not a dated adjudication log. Do not retrospectively invent reasons or timestamps. The original master remains historical and unfinished, with its open disputes preserved.']),
('Agreement and construct validity',['Recorded track agreement is 354/360, primary ambiguity-source agreement 253/360, and entity-specification agreement 166/360. High agreement on intentionally constructed tracks does not establish separability for naturally occurring requests.'])])

pdf('docs/Model_Evaluation_Protocol.pdf','Saved-response evaluation protocol',[
('Reproducible analysis',['Run python code/reproduce.py from the repository. It reads included source files and writes regenerated results/figures under reproduced/. No network, GPU, model download, or new annotation is required for saved-response analysis. Historical inference is archived separately and not rerun by this command.']),
('Execution',['Analyze 120 U queries for each of three LLMs, using supplied binary correctness records. Equivalent names and harmless formatting are accepted by the supplied instructions; incomplete requested lists/comparisons and materially false supporting facts are incorrect. Model identities are associated by query and response content, without publishing private blind-ID keys. One literal None response is matched to its empty blinded export; the original text and normalization flag remain in the scored output.']),
('Cooperative quality',['The supplied final corpus contains 480 responses, four systems on 120 C queries. Three recorded dimensions range from 0 to 2; total/6 is the normalized score. Agreement-source rows number 205; 275 are marked adjudicated. These labels do not establish independent human review or independently verified factual correctness. The proposed prospective re-review rubric is separate from the unverified historical protocol.']),
('Unified action selection',['All 360 queries receive the same action prompt, with track labels hidden. Score ANSWER, INTERPRET, or CLARIFY against the intended action. Report accuracy, balanced accuracy, macro-F1, per-track recall, appropriate X clarification, U/C over-clarification, and confusion matrices. X non-clarification is a policy mismatch; it is not a measured hallucination or harm rate. Always-clarify accuracy is 1/3, with macro-F1 1/6.']),
('Inference and uncertainty',['The recorded repositories are Qwen/Qwen2.5-7B-Instruct, google/gemma-4-E4B-it, and mistralai/Mistral-7B-Instruct-v0.2. Historical commit SHAs are not recorded. Archived settings describe greedy generation, an input budget of 2048 tokens, and output budgets of 100/140/80 for execution/action/legacy conditions. These do not establish a fully locked historical environment or explicit thinking-mode default.']),
('Statistics',['Bootstrap means and paired differences use 5000 resamples at seed 42. Archived CSV row order is retained. Execution and action accuracy use exact two-sided McNemar tests; cooperative scores use 10000 paired sign-flip draws. Holm correction covers the three LLM pairs separately within each primary family. Non-significance is not equivalence; subgroup and dimension comparisons remain descriptive.']),
('Primary versus secondary evidence',['The corrected master uses recorded binary execution labels, cooperative rubric scores, and unified action metrics. Task-aware automatic execution scoring and legacy clarification/abstention weighting are secondary. The original rank-reversal claim is withdrawn. Old supplied summaries are preserved only under archive/supplied_results.'])], body_style='CompactText')

pdf('human_evaluation/cooperative/cooperative_human_annotation_guidelines.pdf','Cooperative response rubric for prospective validation',[
('Status and purpose',['This is a proposed operational guide for a future independent human re-review. It has not been applied to the archived scores and is not claimed to be their historical annotation protocol. A validated replacement for the rejected automatic judge still requires actual independent review. Use anonymous rater identifiers and keep model identities hidden while rating.']),
('Work independently',['Each rater reviews every assigned response without access to another rating, a model name, or a suggested machine score. Record the interpretation, assumptions, sources checked, uncertainty, and rating reasons. Disagreements go to a separately documented adjudication step; preserve both original ratings and the final reason.']),
('Interpretation validity: 0 to 2',['0: the chosen frame is unrelated, arbitrary, or fails to resolve the material ambiguity. 1: the frame is plausible but an important part of the query remains unresolved or the default is weakly justified. 2: the response chooses a coherent, conventional frame that makes the request answerable and explains why it is defensible.']),
('Assumption quality: 0 to 2',['0: material assumptions are hidden, contradictory, or unsupported. 1: assumptions are partly stated but a relevant entity, time window, metric, or scope remains unclear. 2: the response explicitly states the assumptions needed for its frame, bounds the time/competition/statistic, and communicates relevant uncertainty or alternatives.']),
('Answer usefulness: 0 to 2',['0: no substantive answer is given, the answer does not address the chosen frame, or a major factual error defeats the request. 1: the answer is relevant and partly useful but incomplete, insufficiently supported, or missing a requested component. 2: the answer directly and completely addresses the chosen frame and material factual claims have been checked. Do not award 2 solely because the answer is fluent or contains specific numbers.']),
('Factual checks and equivalent wording',['Accept semantically equivalent names and harmless formatting. Use primary sports statistics where available; preserve source URL, event/time snapshot, relevant data, and calculation for derived statistics. A known source mismatch must remain unresolved rather than being marked verified. Missing tables in the experimental condition should not be confused with permission to invent facts.']),
('Anchors',['A response that only says “assume the latest season and use wins” without an answer can receive partial framing credit but no complete usefulness credit. A response that identifies a specific season/competition, discloses a conventional statistic, and gives a checked answer can receive full credit. A response giving wrong championship totals cannot receive full factual-usefulness credit even when its format is correct.']),
('Data recording',['Preserve the original response text exactly, including signs, percentages, and score strings. Avoid spreadsheet conversion of results such as 3-1 into dates. Record three integers, reasons, sources, and adjudication status separately. Preserve blank/missing output distinctions.']),
('Validation after review',['Report exact agreement and quadratic Cohen kappa separately per dimension before adjudication. Compare the proposed judge to an independently rated validation subset before using it as a primary model-ranking metric. Recompute all primary results if labels change, version the updated corpus, and report disagreements rather than overwriting history.'])])

pdf('docs/Execution_Response_Review_Guide.pdf','Execution response review guide',[
('Status',['The original scoring instructions are preserved in STEP1_HUMAN_AUDIT_INSTRUCTIONS.txt. This release guide adds prospective provenance and source-recording requirements. It does not certify that archived labels were independently reviewed.']),
('Binary correctness',['Assign 1 only when the requested answer is fully correct. Assign 0 for an incorrect entity or statistic, missing requested comparison values/list members, an incomplete answer, or materially false supporting statements. Accept equivalent names and harmless formatting. Do not evaluate style.']),
('Reference verification',['Check the gold reference against the appropriate event/time snapshot. Derived statistics require source values, denominator/exclusion rules, and calculations. Resolve a known incorrect or unsupported reference before deciding a response label; document the change and affected model outputs.']),
('Independence and record integrity',['Raters should work independently on identical preserved stimuli, with model identities hidden. Record sources and reasons, and retain a separate documented adjudication outcome. Model-to-blind-ID keys remain private. The public scorer associates content only when recorded labels for identical responses agree.']),
('Current archival observations',['Supplied binary labels agree on 360 records, but eight B-export response strings differ from A and one literal None run output appears as an empty blinded stimulus. Labels for these cases are zero. Their export chronology is not documented, and agreement does not establish independent human authorship.'])])
print('Built five review guides; prospective rubrics did not modify any recorded score.')
